pub struct AddArgs {
    pub name: String,

    #[arg(long)]
    pub kind: KindArg,

    #[arg(long)]
    pub git: Option<String>,

    #[arg(long)]
    pub rev: Option<String>,

    #[arg(long)]
    pub npm: Option<String>,

    #[arg(long, default_value_t = String::from("0.0.0"))]
